import sys, random, itertools
sys.path.insert(0, '/workspace/project')
sys.path.insert(0, '/workspace/tests')
from syntax import parse, PolicyError, MAX_DISTINCT_NONMATCH, MAX_NONMATCH_PATH
from brute import check

KINDS = ('match', 'startswith', 'endswith', 'contains')


def rand_path(rng, names, maxlen):
    return tuple(rng.choice(names) for _ in range(rng.randint(0, min(maxlen, len(names) * 2))))


def rand_pred(rng, names, depth, nonmatch, pathmax):
    if depth <= 1 or rng.random() < 0.35:
        kind = rng.choice(KINDS)
        limit = MAX_NONMATCH_PATH if kind != 'match' else pathmax
        path = rand_path(rng, names, limit)
        if kind != 'match':
            key = (kind, path)
            if key not in nonmatch:
                if len(nonmatch) >= MAX_DISTINCT_NONMATCH:
                    kind, path = rng.choice(list(nonmatch))
                else:
                    nonmatch.add(key)
        return (kind, path)
    r = rng.random()
    if r < 0.35:
        return ('not', rand_pred(rng, names, depth - 1, nonmatch, pathmax))
    return (rng.choice(('and', 'or')),
            rand_pred(rng, names, depth - 1, nonmatch, pathmax),
            rand_pred(rng, names, depth - 1, nonmatch, pathmax))


def gen(rng, names, pathmax):
    nonmatch = set()
    rules = []
    for _ in range(rng.randint(0, 6)):
        pred = rand_pred(rng, names, rng.randint(1, 5), nonmatch, pathmax)
        rules.append((pred, rng.random() < 0.6))
    def show(p):
        if p[0] in ('and', 'or'):
            return '(%s %s %s)' % (show(p[1]), p[0], show(p[2]))
        if p[0] == 'not':
            return 'not(%s)' % show(p[1])
        return '%s(%s)' % (p[0], ','.join(p[1]))
    return ' '.join('%s %s;' % (show(p), 'allow' if a else 'drop') for p, a in rules)


def main(seed, count, services, limit, depth):
    rng = random.Random(seed)
    names = [chr(65 + i) for i in range(services)]
    bad = 0
    for i in range(count):
        text = gen(rng, names, 6)
        try:
            parse(text)
        except PolicyError:
            continue
        err = check(text, names, limit=limit, depth=depth)
        if err:
            bad += 1
            print('FAIL %r: %s' % (text, err))
            if bad > 3:
                break
    print('fuzz2 seed=%d n=%d svc=%d failures=%d' % (seed, count, services, bad))


